package echo

import (
	"fmt"
	"math/rand"
	"strings"
	"testing"
	"time"
)

// reference: enumerate all route paths that match request path
func refMatch(route, req string) bool {
	rs := strings.Split(strings.TrimPrefix(route, "/"), "/")
	qs := strings.Split(strings.TrimPrefix(req, "/"), "/")
	var rec func(i, j int) bool
	rec = func(i, j int) bool {
		if i == len(rs) {
			return j == len(qs)
		}
		switch {
		case rs[i] == "*":
			return true
		case strings.HasPrefix(rs[i], ":"):
			if j >= len(qs) {
				return false
			}
			return rec(i+1, j+1)
		default:
			if j >= len(qs) || qs[j] != rs[i] {
				return false
			}
			return rec(i+1, j+1)
		}
	}
	return rec(0, 0)
}

func TestZZFuzzRouter(t *testing.T) {
	segPool := []string{"a", "b", ":p", "*", ""}
	rand.Seed(42)
	var routePaths, reqPaths []string
	for i := 0; i < 400; i++ {
		n := 1 + rand.Intn(3)
		var segs []string
		for j := 0; j < n; j++ {
			segs = append(segs, segPool[rand.Intn(len(segPool))])
		}
		routePaths = append(routePaths, "/"+strings.Join(segs, "/"))
	}
	for i := 0; i < 400; i++ {
		n := 0 + rand.Intn(4)
		var segs []string
		for j := 0; j < n; j++ {
			segs = append(segs, []string{"a", "b", "x"}[rand.Intn(3)])
		}
		reqPaths = append(reqPaths, "/"+strings.Join(segs, "/"))
	}

	for _, rp := range routePaths {
		e := New()
		e.GET(rp, func(c Context) error { return nil })
		// add a couple of extra routes for tree complexity
		e.GET("/a/b", func(c Context) error { return nil })
		e.GET("/a/:p/c", func(c Context) error { return nil })
		e.GET("/*", func(c Context) error { return nil })
		routes := []string{rp, "/a/b", "/a/:p/c", "/*"}
		for _, qp := range reqPaths {
			func() {
				defer func() {
					if r := recover(); r != nil {
						fmt.Printf("PANIC route=%q req=%q: %v\n", rp, qp, r)
					}
				}()
				done := make(chan string, 1)
				go func() {
					defer func() {
						if r := recover(); r != nil {
							done <- fmt.Sprintf("panic: %v", r)
						}
					}()
					c := e.NewContext(nil, nil)
					e.router.Find("GET", qp, c)
					h := c.Handler()
					matched := ""
					if h != nil && h != NotFoundHandler {
						matched = c.Path()
					}
					done <- matched
				}()
				select {
				case got := <-done:
					if strings.HasPrefix(got, "panic:") {
						fmt.Printf("PANIC2 route=%q req=%q: %s\n", rp, qp, got)
						return
					}
					var expect []string
					for _, r := range routes {
						if refMatch(r, qp) {
							expect = append(expect, r)
						}
					}
					if len(expect) == 0 && got != "" {
						fmt.Printf("MISMATCH-NOMATCH route=%q req=%q got=%q\n", rp, qp, got)
					}
					if len(expect) > 0 && got == "" {
						fmt.Printf("MISMATCH-NOTFOUND route=%q req=%q expect=%v\n", rp, qp, expect)
					}
					if got != "" && len(expect) > 0 {
						found := false
						for _, x := range expect {
							if x == got {
								found = true
							}
						}
						if !found {
							fmt.Printf("MISMATCH-OTHER route=%q req=%q got=%q expect=%v\n", rp, qp, got, expect)
						}
					}
				case <-time.After(2 * time.Second):
					fmt.Printf("HANG route=%q req=%q\n", rp, qp)
				}
			}()
		}
	}
}
EOF
