  7	type (
  8		// Group is a set of sub-routes for a specified route. It can be used for inner
  9		// routes that share a common middleware or functionality that should be separate
 10		// from the parent echo instance while still inheriting from it.
 11		Group struct {
 12			common
 13			host       string
 14			prefix     string
