 17		}
 18	)
 19	
 20	// Use implements `Echo#Use()` for sub-routes within the Group.
 21	func (g *Group) Use(middleware ...MiddlewareFunc) {
 22		g.middleware = append(g.middleware, middleware...)
 23		if len(g.middleware) == 0 {
 24			return
 25		}
 26		// Allow all requests to reach the group as they might get dropped if router
 27		// doesn't find a match, making none of the group middleware process.
 28		g.Any("", NotFoundHandler)
 29		g.Any("/*", NotFoundHandler)
 30	}
 31	
 32	// CONNECT implements `Echo#CONNECT()` for sub-routes within the Group.
 33	func (g *Group) CONNECT(path string, h HandlerFunc, m ...MiddlewareFunc) *Route {
 34		return g.Add(http.MethodConnect, path, h, m...)
 35	}
 36	
 37	// DELETE implements `Echo#DELETE()` for sub-routes within the Group.
 38	func (g *Group) DELETE(path string, h HandlerFunc, m ...MiddlewareFunc) *Route {
 39		return g.Add(http.MethodDelete, path, h, m...)
 40	}
 41	
