 53	func (g *Group) OPTIONS(path string, h HandlerFunc, m ...MiddlewareFunc) *Route {
 54		return g.Add(http.MethodOptions, path, h, m...)
 55	}
 56	
 57	// PATCH implements `Echo#PATCH()` for sub-routes within the Group.
 58	func (g *Group) PATCH(path string, h HandlerFunc, m ...MiddlewareFunc) *Route {
 59		return g.Add(http.MethodPatch, path, h, m...)
 60	}
 61	
 62	// POST implements `Echo#POST()` for sub-routes within the Group.
 63	func (g *Group) POST(path string, h HandlerFunc, m ...MiddlewareFunc) *Route {
 64		return g.Add(http.MethodPost, path, h, m...)
 65	}
