 68	func (g *Group) PUT(path string, h HandlerFunc, m ...MiddlewareFunc) *Route {
 69		return g.Add(http.MethodPut, path, h, m...)
 70	}
 71	
 72	// TRACE implements `Echo#TRACE()` for sub-routes within the Group.
 73	func (g *Group) TRACE(path string, h HandlerFunc, m ...MiddlewareFunc) *Route {
 74		return g.Add(http.MethodTrace, path, h, m...)
 75	}
 76	
 77	// Any implements `Echo#Any()` for sub-routes within the Group.
 78	func (g *Group) Any(path string, handler HandlerFunc, middleware ...MiddlewareFunc) []*Route {
 79		routes := make([]*Route, len(methods))
 80		for i, m := range methods {
 81			routes[i] = g.Add(m, path, handler, middleware...)
 82		}
 83		return routes
 84	}
 85	
 86	// Match implements `Echo#Match()` for sub-routes within the Group.
 87	func (g *Group) Match(methods []string, path string, handler HandlerFunc, middleware ...MiddlewareFunc) []*Route {
 88		routes := make([]*Route, len(methods))
 89		for i, m := range methods {
 90			routes[i] = g.Add(m, path, handler, middleware...)
 91		}
 92		return routes
 93	}
 94	
 95	// Group creates a new sub-group with prefix and optional sub-group-level middleware.
 96	func (g *Group) Group(prefix string, middleware ...MiddlewareFunc) (sg *Group) {
 97		m := make([]MiddlewareFunc, 0, len(g.middleware)+len(middleware))
 98		m = append(m, g.middleware...)
 99		m = append(m, middleware...)
100		sg = g.echo.Group(g.prefix+prefix, m...)
101		sg.host = g.host
102		return
103	}
104	
105	// Static implements `Echo#Static()` for sub-routes within the Group.
106	func (g *Group) Static(prefix, root string) {
107		g.static(prefix, root, g.GET)
108	}
109	
110	// File implements `Echo#File()` for sub-routes within the Group.
111	func (g *Group) File(path, file string) {
112		g.file(path, file, g.GET)
113	}
114	
115	// Add implements `Echo#Add()` for sub-routes within the Group.
116	func (g *Group) Add(method, path string, handler HandlerFunc, middleware ...MiddlewareFunc) *Route {
117		// Combine into a new slice to avoid accidentally passing the same slice for
118		// multiple routes, which would lead to later add() calls overwriting the
119		// middleware from earlier calls.
120		m := make([]MiddlewareFunc, 0, len(g.middleware)+len(middleware))
121		m = append(m, g.middleware...)
122		m = append(m, middleware...)
123		return g.echo.add(g.host, method, g.prefix+path, handler, m...)
124	}

