// BodyLimitWithConfig returns a BodyLimit middleware with config.
// See: `BodyLimit()`.
func BodyLimitWithConfig(config BodyLimitConfig) echo.MiddlewareFunc {
	// Defaults
	if config.Skipper == nil {
		config.Skipper = DefaultBodyLimitConfig.Skipper
	}

	limit, err := bytes.Parse(config.Limit)
	if err != nil {
		panic(fmt.Errorf("echo: invalid body-limit=%s", config.Limit))
	}
	config.limit = limit
	pool := limitedReaderPool(config)

119	// bindData will bind data ONLY fields in destination struct that have EXPLICIT tag
120	func (b *DefaultBinder) bindData(destination interface{}, data map[string][]string, tag string) error {
121		if destination == nil || len(data) == 0 {
122			return nil
123		}
124		typ := reflect.TypeOf(destination).Elem()
125		val := reflect.ValueOf(destination).Elem()
126	
127		// Map
128		if typ.Kind() == reflect.Map {
129			for k, v := range data {
130				val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
131			}
132			return nil
133		}
134	
135		// !struct
136		if typ.Kind() != reflect.Struct {
137			return errors.New("binding element must be a struct")
138		}
139	
140		for i := 0; i < typ.NumField(); i++ {
141			typeField := typ.Field(i)
142			structField := val.Field(i)
143			if !structField.CanSet() {
144				continue
145			}
146			structFieldKind := structField.Kind()
147			inputFieldName := typeField.Tag.Get(tag)
148	
149			if inputFieldName == "" {
150				// If tag is nil, we inspect if the field is a not BindUnmarshaler struct and try to bind data into it (might contains fields with tags).
151				// structs that implement BindUnmarshaler are binded only when they have explicit tag
152				if _, ok := structField.Addr().Interface().(BindUnmarshaler); !ok && structFieldKind == reflect.Struct {
153					if err := b.bindData(structField.Addr().Interface(), data, tag); err != nil {
154						return err
155					}
156				}
157				// does not have explicit tag and is not an ordinary struct - so move to next field
158				continue
159			}
160	
161			inputValue, exists := data[inputFieldName]
162			if !exists {
163				// Go json.Unmarshal supports case insensitive binding.  However the
164				// url params are bound case sensitive which is inconsistent.  To
165				// fix this we must check all of the map values in a
166				// case-insensitive search.
167				for k, v := range data {
168					if strings.EqualFold(k, inputFieldName) {
169						inputValue = v
170						exists = true
171						break
172					}
173				}
174			}
175	
176			if !exists {
177				continue
178			}
179	
180			// Call this first, in case we're dealing with an alias to an array type
181			if ok, err := unmarshalField(typeField.Type.Kind(), inputValue[0], structField); ok {
182				if err != nil {
183					return err
184				}
185				continue
186			}
187	
188			numElems := len(inputValue)
189			if structFieldKind == reflect.Slice && numElems > 0 {
190				sliceOf := structField.Type().Elem().Kind()
191				slice := reflect.MakeSlice(structField.Type(), numElems, numElems)
192				for j := 0; j < numElems; j++ {
193					if err := setWithProperType(sliceOf, inputValue[j], slice.Index(j)); err != nil {
194						return err
195					}
196				}
197				val.Field(i).Set(slice)
198			} else if err := setWithProperType(typeField.Type.Kind(), inputValue[0], structField); err != nil {
199				return err
200	
201			}
202		}
203		return nil
204	}
