270	func unmarshalFieldPtr(value string, field reflect.Value) (bool, error) {
271		if field.IsNil() {
272			// Initialize the pointer to a nil value
273			field.Set(reflect.New(field.Type().Elem()))
274		}
275		return unmarshalFieldNonPtr(value, field.Elem())
276	}
